// Intrinsic string mapping types should preserve lone surrogates, matching tsc.
// A lone surrogate has no case mapping, so it passes through unchanged.
type U = Uppercase<"\uD800">;
type L = Lowercase<"A\uD800B">;
type C = Capitalize<"\uDC00x">;
type Un = Uncapitalize<"\uD834X">;

const u: "\uD800" = "x" as unknown as U;
const l: "a\uD800b" = "x" as unknown as L;

// Template literal type inference consumes one code point at a time, matching
// the string iterator (`[x, ..._] = s`) rather than UTF-16 code-unit indexing
// (`s[0]`). A supplementary code point is therefore kept whole rather than being
// split into its surrogate halves: Head<"😀abc"> is "😀" and Rest<"😀abc"> is
// "abc". This intentionally diverges from tsc, which advances one code unit at a
// time and yields the high surrogate "\uD83D".
type Head<S extends string> = S extends `${infer H}${infer _R}` ? H : never;
type Rest<S extends string> = S extends `${infer _H}${infer R}` ? R : never;

type H = Head<"\u{1F600}abc">;
type R = Rest<"\u{1F600}abc">;

const h: "\u{1F600}" = "x" as unknown as H;
const r: "abc" = "x" as unknown as R;

// Reassembling the head and rest reproduces the original string.
type Both = `${H}${R}`;
const both: "\u{1F600}abc" = "x" as unknown as Both;

// Template literal type inference over a string containing a lone surrogate
// should preserve the surrogate, matching tsc. This baseline verifies the
// inferred lone surrogate is preserved rather than corrupted to U+FFFD.
type Head<S extends string> = S extends `${infer H}${infer _R}` ? H : never;
type Rest<S extends string> = S extends `${infer _H}${infer R}` ? R : never;

type H = Head<"\uD800abc">;
type R = Rest<"\uD800abc">;

const h: "\uD800" = "x" as unknown as H;
const r: "abc" = "x" as unknown as R;

const sym = Symbol("")
type Orig = { [k: string]: any, str: any, [sym]: any }

type Okay = Exclude<keyof Orig, never>
// type Okay = string | number | typeof sym

type Remapped = { [K in keyof Orig as {} extends Record<K, any> ? never : K]: any }
/* type Remapped = {
    str: any;
    [sym]: any;
} */
// no string index signature, right?

type Oops = Exclude<keyof Remapped, never>
declare let x: Oops;
x = sym;
x = "str";
// type Oops = typeof sym <-- what happened to "str"?

// equivalently, with an unresolved generic (no `exclude` shenanigans, since conditions won't execute):
function f<T>() {
    type Orig = { [k: string]: any, str: any, [sym]: any } & T;

    type Okay = keyof Orig;
    let a: Okay;
    a = "str";
    a = sym;
    a = "whatever";
    // type Okay = string | number | typeof sym

    type Remapped = { [K in keyof Orig as {} extends Record<K, any> ? never : K]: any }
    /* type Remapped = {
        str: any;
        [sym]: any;
    } */
    // no string index signature, right?

    type Oops = keyof Remapped;
    let x: Oops;
    x = sym;
    x = "str";
}

// and another generic case with a _distributive_ mapping, to trigger a different branch in `getIndexType`
function g<T>() {
    type Orig = { [k: string]: any, str: any, [sym]: any } & T;

    type Okay = keyof Orig;
    let a: Okay;
    a = "str";
    a = sym;
    a = "whatever";
    // type Okay = string | number | typeof sym

    type NonIndex<T extends PropertyKey> = {} extends Record<T, any> ? never : T;
    type DistributiveNonIndex<T extends PropertyKey> = T extends unknown ? NonIndex<T> : never;

    type Remapped = { [K in keyof Orig as DistributiveNonIndex<K>]: any }
    /* type Remapped = {
        str: any;
        [sym]: any;
    } */
    // no string index signature, right?

    type Oops = keyof Remapped;
    let x: Oops;
    x = sym;
    x = "str";
    x = "whatever"; // error
}

